target_code: Here's the Go translation of the main structure with function signatures and types (no implementations):

```go
package main

import "unsafe"

// Global state variables (avoid in production; shown for structural fidelity)
var (
	ans     [][][]byte // equivalent to char***: slice of solutions, each solution is slice of rows, each row is []byte
	path    [][]byte   // equivalent to char**: current board state, slice of rows
	ansTop  int        // number of solutions found
	pathTop int        // current depth / queens placed
)

// copyPath copies current path into ans
func copyPath(n int) {
	tempPath := make([][]byte, pathTop)
	for i := 0; i < pathTop; i++ {
		tempPath[i] = make([]byte, n+1)
		copy(tempPath[i], path[i])
		tempPath[i][n] = 0 // null terminator (though Go strings don't require it)
	}
	ans = append(ans, tempPath)
}

// isValid checks if placing queen at (x, y) is safe
func isValid(x, y, n int) bool {
	// Check row and column
	for i := 0; i < n; i++ {
		if path[y][i] == 'Q' || path[i][x] == 'Q' {
			return false
		}
	}

	// Check diagonals
	i, j := y-1, x-1
	for i >= 0 && j >= 0 {
		if path[i][j] == 'Q' {
			return false
		}
		i--
		j--
	}

	i, j = y+1, x+1
	for i < n && j < n {
		if path[i][j] == 'Q' {
			return false
		}
		i++
		j++
	}

	i, j = y-1, x+1
	for i >= 0 && j < n {
		if path[i][j] == 'Q' {
			return false
		}
		i--
		j++
	}

	i, j = y+1, x-1
	for i < n && j >= 0 {
		if path[i][j] == 'Q' {
			return false
		}
		i++
		j--
	}

	return true
}

// backTracking performs DFS search
func backTracking(n, depth int) {
	if pathTop == n {
		copyPath(n)
		return
	}

	for i := 0; i < n; i++ {
		if isValid(i, depth, n) {
			path[depth][i] = 'Q'
			pathTop++

			backTracking(n, depth+1)

			path[depth][i] = '.'
			pathTop--
		}
	}
}

// initPath initializes the board with '.'
func initPath(n int) {
	path = make([][]byte, n)
	for i := 0; i < n; i++ {
		path[i] = make([]byte, n+1)
		for j := 0; j < n; j++ {
			path[i][j] = '.'
		}
		path[i][n] = 0 // null terminator
	}
}

// solveNQueens is the public entry point
func solveNQueens(n int) ([][]string, []int) {
	ans = nil
	path = nil
	ansTop = 0
	pathTop = 0

	initPath(n)
	backTracking(n, 0)

	// Convert [][][]byte to [][]string
	result := make([][]string, len(ans))
	for i := range ans {
		result[i] = make([]string, len(ans[i]))
		for j := range ans[i] {
			// Trim null terminator and convert to string
			result[i][j] = string(ans[i][j][:len(ans[i][j])-1])
		}
	}

	// Return column sizes (all n)
	colSizes := make([]int, len(ans))
	for i := range colSizes {
		colSizes[i] = n
	}

	return result, colSizes
}
```

Note: The Go version replaces C-style manual memory management with slices and built-in allocation. The global variables are preserved for structural fidelity to the original C code, though idiomatic Go would avoid globals by using a struct-based approach.

